// Assembles the browser side of the config panels. The sources in shared-ui/ are ES modules (testable in Node); a
// host client bundle is one script, so this strips the import/export keywords and wraps the result in a function
// scope: `const aiwukConfig = (() => {...})()` exposes only createPanelKit / PANELS / panelDictionaries.
//   node shared-ui/build.mjs           regenerate packages/{global-memory,omni-search,autocomplete}/client fragments
//   node shared-ui/build.mjs --check   fail when a generated file is stale (run by tests/config-panel-build.test.mjs)
import { readFile, writeFile, readdir, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const base = dirname(dirname(fileURLToPath(import.meta.url)));
const ui = name => join(base, 'shared-ui', name);
const escapeNonAscii = text => text.replace(/[^\x20-\x7e\n]/g, c => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`);
/** Drop module syntax: single-line imports go away, `export ` prefixes are removed. */
const plain = source => source.replace(/^import [^\n]*\n/gm, '').replace(/^export (?=(?:const|function|async function|let) )/gm, '').replace(/^export \{[^}]*\};?\n/gm, '');

export const TARGETS = Object.freeze([
  { dir: 'packages/global-memory', module: '@aiwuk/memory', fragment: 'client/00-panel.js', client: true },
  { dir: 'packages/omni-search', module: '@aiwuk/search', fragment: 'client/00-panel.js', client: true },
  // The root package assembles its own client.js (scripts/build-client.mjs) from client/*.js.
  { dir: '.', module: '@aiwuk/team', fragment: 'client/03c-config-panel.js', client: false },
  // Autocomplete assembles its own client.js (scripts/build-client.mjs) from client/*.js.
  { dir: 'packages/autocomplete', module: '@aiwuk/autocomplete', fragment: 'client/02c-config-panel.js', client: false },
]);

/** The generated, collision-free module body. */
export async function panelModule() {
  const [logic, fields, panel, catalog, brand, en, zh] = await Promise.all(['config-logic.js', 'fields.js', 'config-panel.js', 'catalog.json', 'brand-text.js', 'locale/en.json', 'locale/zh.json'].map(name => readFile(ui(name), 'utf8')));
  const brandText = plain(brand).replace(/^\/\/.*\n/gm, '');
  const dictionaries = `const DICTIONARIES = ${escapeNonAscii(JSON.stringify({ en: JSON.parse(en), zh: JSON.parse(zh) }))};
const CATALOG = ${escapeNonAscii(JSON.stringify(JSON.parse(catalog)))};
/** en / zh dictionaries of one panel: shared texts, catalog labels (ref.<REF>) and the Mothership name filled in. */
function panelDictionaries(panel) {
  const out = {};
  for (const lang of ['en', 'zh']) {
    const dict = { ...DICTIONARIES[lang] };
    for (const field of panel.fields) {
      const entry = CATALOG.find(item => item.ref === field.ref);
      if (entry) dict['ref.' + entry.ref] = entry.label[lang];
    }
    for (const key of Object.keys(dict)) dict[key] = dict[key].replaceAll('{mothership}', BRAND_TEXT.mothership[lang]);
    out[lang] = dict;
  }
  return out;
}`;
  const body = [brandText, plain(logic), plain(fields), dictionaries, plain(panel)].map(part => part.replace(/\n+$/, '')).join('\n');
  return `(() => {\n${body}\nreturn { createPanelKit, PANELS, panelDictionaries };\n})()`;
}

const HEADER = '// @generated by shared-ui/build.mjs from shared-ui/*.js, catalog.json and locale/*.json — edit those, then run node shared-ui/build.mjs.';
export async function fragment() {
  return `${HEADER}\n    const aiwukConfig = ${(await panelModule()).split('\n').map((line, i) => (i ? `    ${line}` : line)).join('\n')};\n`;
}

const CLIENT_HEAD = target => `${HEADER}
// Registers the plugins.bundle.config panel of ${target.module}. React comes from the host module table.
window.__ModuleLoader__.load({
  id: '${target.module}',
  factory(require) {
`;
const CLIENT_TAIL = `
    return plugin;
  },
});
`;
/** client.js of a standalone target: fragments client/NN-*.js in name order. */
export async function assembleClient(target) {
  const dir = join(base, target.dir, 'client');
  const names = (await readdir(dir)).filter(name => /^\d{2}[a-z]?-[a-z0-9-]+\.js$/.test(name)).sort();
  const parts = await Promise.all(names.map(async name => {
    const text = await readFile(join(dir, name), 'utf8');
    return (name === target.fragment.split('/').pop() ? text.replace(/^\/\/ @generated[^\n]*\n/, '') : text).replace(/\n+$/, '\n');
  }));
  return CLIENT_HEAD(target) + parts.join('\n') + CLIENT_TAIL;
}

export async function build({ check = false } = {}) {
  const stale = [];
  const generated = await fragment();
  for (const target of TARGETS) {
    const fragmentPath = join(base, target.dir, target.fragment);
    const write = async (path, text) => {
      const current = await readFile(path, 'utf8').catch(() => null);
      if (current === text) return;
      if (check) { stale.push(path.replace(base + '/', '')); return; }
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, text);
    };
    await write(fragmentPath, generated);
    if (target.client && !check) await write(join(base, target.dir, 'client.js'), await assembleClient(target));
    else if (target.client) await write(join(base, target.dir, 'client.js'), await assembleClient(target).catch(() => ''));
  }
  return stale;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const check = process.argv.includes('--check');
  const stale = await build({ check });
  if (stale.length) { console.error(`config panel outputs are stale: ${stale.join(', ')} (run node shared-ui/build.mjs)`); process.exit(1); }
  console.log(check ? 'CONFIG_PANEL_BUILD_OK' : 'config panel outputs built');
}
